from odoo import http
from odoo.http import request

class HospitalApi(http.Controller):

    @http.route('/hospital/patients', type='json', auth='user')
    def patients(self, limit=10):
        return request.env['hospital.patient'].search_read(
            [], ['reference', 'name', 'age'], limit=limit)

